# ---------------------------------------------------------------------------
# Phase 7 -- three misdirecting refusals, each its own case (Finding 4;
# Decision 13). The spec's own word budget forced one scenario each; these
# are three distinct defects with three distinct causes, opened into
# concrete cases rather than carrying that thinness forward.
# ---------------------------------------------------------------------------


class PinPublishedTimeoutBudgetTests(unittest.TestCase):
    """Case A -- `_verify_commit_reachable()`'s probe must own its own time
    budget, separate from `GIT_TIMEOUT_SECONDS` (120s), which the two local
    calls around it (`rev-parse`, `cat-file -e`) legitimately never need
    more than.

    Measured against the live remote this skill targets, transferring
    12.4 MiB on a slow link: 209s once, 27s on an identical re-run of the
    SAME commit. A shared budget made the verdict track the LINK, not the
    pin -- the first, slower run reported the commit as "not pushed" from
    transfer time alone, and a whole session concluded from that one
    measurement that this repository could never publish on that
    connection. A true measurement, a false conclusion, because the
    message named the wrong cause.

    Every test in this class has a reachable red: before this task,
    `jobfolder` exposes no `PIN_PUBLISHED_TIMEOUT_SECONDS` attribute at
    all, and the fetch call passes no `timeout` keyword of its own, so it
    silently inherits `_run_git`'s `GIT_TIMEOUT_SECONDS` default.
    """

    def test_pin_published_timeout_is_a_separate_constant_from_git_timeout(
        self,
    ) -> None:
        """The two budgets must stop being one -- read as two distinct
        module constants, not a single shared default reused twice."""
        self.assertTrue(
            hasattr(JOBFOLDER, "PIN_PUBLISHED_TIMEOUT_SECONDS"),
            "jobfolder.py declares no PIN_PUBLISHED_TIMEOUT_SECONDS at all",
        )
        self.assertNotEqual(
            JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS,
            JOBFOLDER.GIT_TIMEOUT_SECONDS,
            "pin-published must not share its budget with the local git "
            "calls around it",
        )
        self.assertGreater(
            JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS,
            209,
            "the new budget must cover the measured 209s worst case with "
            "headroom, not merely equal it",
        )

    def test_the_fetch_call_alone_receives_the_new_budget(self) -> None:
        """`pin-published` is the ONLY condition that reaches the network;
        the local `init` (and, by the same rule elsewhere in this module,
        `rev-parse`/`cat-file -e`) never needs more than the 120s local
        default, so only the fetch call's own `timeout` keyword may differ.
        """
        recorded = []

        def fake_run_git(args, *, cwd, timeout=None):
            recorded.append((list(args), timeout))
            return unittest.mock.Mock(returncode=0, stdout="", stderr="")

        with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
            JOBFOLDER._verify_commit_reachable(
                "c" * 40, "https://example.invalid/repo.git", "main"
            )

        by_command = {args[0]: timeout for args, timeout in recorded}
        self.assertEqual(
            by_command["fetch"], JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS,
            "the fetch call must receive the dedicated pin-published budget",
        )
        self.assertNotEqual(
            by_command["init"], JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS,
            "the local init call must not be widened along with the fetch",
        )

    def test_a_measured_209s_transfer_is_not_reported_as_unpublished(self) -> None:
        """The exact regression this task fixes, reproduced at the
        `_run_git` seam: a transfer that exceeds the OLD shared 120s
        budget but fits inside the new, separate one must not raise --
        the probe still never runs anywhere but the scratch repository."""
        call_timeouts = []

        def fake_run_git(args, *, cwd, timeout=None):
            if list(args)[:1] == ["fetch"]:
                # `timeout=None` means the caller passed no keyword at all,
                # which (both before and after this task) means "whatever
                # `_run_git`'s own default is" -- mimicked here explicitly
                # since mocking `_run_git` bypasses its real default.
                effective = (
                    timeout if timeout is not None else JOBFOLDER.GIT_TIMEOUT_SECONDS
                )
                call_timeouts.append(effective)
                if effective <= JOBFOLDER.GIT_TIMEOUT_SECONDS:
                    raise JOBFOLDER.JobFolderError(
                        "git fetch --dry-run --depth 1 ... timed out after "
                        f"{effective}s"
                    )
            return unittest.mock.Mock(returncode=0, stdout="", stderr="")

        with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
            self.assertIsNone(
                JOBFOLDER._verify_commit_reachable(
                    "c" * 40, "https://example.invalid/repo.git", "main"
                )
            )
        self.assertEqual(call_timeouts, [JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS])

    def test_a_genuinely_expired_pin_published_probe_still_refuses(self) -> None:
        """The wider budget is headroom, not an unconditional pass: a
        timeout that exceeds even the new budget must still refuse, naming
        the timeout -- never silently swallowed."""

        def fake_run_git(args, *, cwd, timeout=None):
            if list(args)[:1] == ["fetch"]:
                raise JOBFOLDER.JobFolderError(
                    f"git fetch --dry-run --depth 1 ... timed out after {timeout}s"
                )
            return unittest.mock.Mock(returncode=0, stdout="", stderr="")

        with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
            with self.assertRaises(JOBFOLDER.JobFolderError) as ctx:
                JOBFOLDER._verify_commit_reachable(
                    "c" * 40, "https://example.invalid/repo.git", "main"
                )
        self.assertIn("timed out", str(ctx.exception))
        self.assertNotIn("not pushed", str(ctx.exception).lower())

    def test_the_weight_reader_is_never_called_on_the_timeout_branch(self) -> None:
        """(Lock 6) `except GitTimeoutError` (`:2559-2578`) is
        byte-unchanged and must never reach the weight reader: sharing one
        message between a timeout and a confirmed refusal is the exact
        defect this branch split already exists to prevent (Finding 4
        case A).
        """

        def fake_run_git(args, *, cwd, timeout=None):
            raise JOBFOLDER.GitTimeoutError(
                f"git {' '.join(args)} timed out after {timeout}s"
            )

        with unittest.mock.patch.object(
            JOBFOLDER, "_unpushed_weight_from_cache"
        ) as mock_weight_reader:
            with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
                with self.assertRaises(JOBFOLDER.JobFolderError) as ctx:
                    JOBFOLDER._verify_commit_reachable(
                        "c" * 40, "https://example.invalid/repo.git", "main"
                    )
            mock_weight_reader.assert_not_called()

        message = str(ctx.exception)
        self.assertIn("could not be finished asking", message)
        self.assertNotIn("push it to", message)
        self.assertNotIn("beyond the last state", message)


class PinWeightTimeoutBudgetTests(unittest.TestCase):
    """(Design Decision 5) The weight reader's own timeout budget is a
    THIRD distinct module constant -- not `GIT_TIMEOUT_SECONDS` (the
    ordinary local-call default) and not `PIN_PUBLISHED_TIMEOUT_SECONDS`
    (the network probe's own budget) -- and only the reader's own three
    git calls may carry it. Measured, not invented: see
    `apply-progress.md` for the raw timings this value was derived from.
    """

    def test_pin_weight_timeout_is_a_third_distinct_constant(self) -> None:
        self.assertTrue(
            hasattr(JOBFOLDER, "PIN_WEIGHT_TIMEOUT_SECONDS"),
            "jobfolder.py declares no PIN_WEIGHT_TIMEOUT_SECONDS at all",
        )
        self.assertNotEqual(
            JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS, JOBFOLDER.GIT_TIMEOUT_SECONDS
        )
        self.assertNotEqual(
            JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS,
            JOBFOLDER.PIN_PUBLISHED_TIMEOUT_SECONDS,
        )
        self.assertLess(
            JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS, JOBFOLDER.GIT_TIMEOUT_SECONDS,
            "the local walk's own budget must read as the cheap local "
            "read at a glance, unambiguously below the ordinary local "
            "git default",
        )

    def test_only_the_readers_three_calls_receive_the_new_budget(self) -> None:
        recorded = []

        def fake_run_git(args, *, cwd, timeout=None):
            recorded.append((list(args)[0] if args else None, timeout))
            if list(args)[:1] == ["config"]:
                return unittest.mock.Mock(
                    returncode=0,
                    stdout="remote.origin.url https://example.invalid/repo.git\n",
                    stderr="",
                )
            if list(args)[:1] == ["rev-parse"]:
                return unittest.mock.Mock(returncode=0, stdout="a" * 40 + "\n", stderr="")
            return unittest.mock.Mock(returncode=0, stdout="0\n", stderr="")

        with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
            weight = JOBFOLDER._unpushed_weight_from_cache(
                Path("/some/target"), "c" * 40,
                "https://example.invalid/repo.git", "main",
            )

        self.assertTrue(weight.measured)
        self.assertEqual(len(recorded), 3, recorded)
        for _verb, timeout in recorded:
            self.assertEqual(timeout, JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS)

    def test_the_probes_own_init_and_fetch_calls_never_receive_the_weight_budget(
        self,
    ) -> None:
        """Mutation to survive: passing the new budget to the probe's
        local `init` call too, widening it along with the reader.
        """
        recorded = []

        def fake_run_git(args, *, cwd, timeout=None):
            recorded.append((list(args)[0] if args else None, timeout))
            if list(args)[:1] == ["fetch"]:
                raise JOBFOLDER.JobFolderError(
                    "git fetch --dry-run exited 128: not our ref"
                )
            return unittest.mock.Mock(returncode=0, stdout="", stderr="")

        with unittest.mock.patch.object(JOBFOLDER, "_run_git", side_effect=fake_run_git):
            with self.assertRaises(JOBFOLDER.JobFolderError):
                JOBFOLDER._verify_commit_reachable(
                    "c" * 40, "https://example.invalid/repo.git", "main",
                    target=Path("/some/target"),
                )

        by_verb: dict[str | None, list] = {}
        for verb, timeout in recorded:
            by_verb.setdefault(verb, []).append(timeout)

        self.assertNotIn(
            JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS, by_verb.get("init", []),
            "the probe's local init call must not be widened along with "
            "the reader's own budget",
        )
        self.assertNotIn(
            JOBFOLDER.PIN_WEIGHT_TIMEOUT_SECONDS, by_verb.get("fetch", []),
            "the network probe's own fetch call keeps its own "
            "PIN_PUBLISHED_TIMEOUT_SECONDS budget",
        )


class EntrypointJobFolderDirectoryTests(unittest.TestCase):
    """Case B -- `guard_entrypoint()` handed the job folder DIRECTORY
    itself (holding `run-config.json` + `runner.ipynb`) instead of the
    notebook FILE inside it must say what it wanted, what it got, and what
    to type -- never the generic shape-mismatch message, which reads as
    though the folder were in the wrong location and sends the caller to
    regenerate a job that was sound.

    Every test in this class has a reachable red: before this task,
    `guard_entrypoint()` has no special case for this shape at all, so a
    job folder directory falls straight into the generic "does not stay
    under ... nor under ..." refusal, which names neither a file nor a
    notebook path.
    """

    def test_a_job_folder_directory_names_the_notebook_inside_it(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            job_dir = _make_job_folder(target, "svc", "job-a")
            (job_dir / "run-config.json").write_text("{}", encoding="utf-8")
            notebook = job_dir / "runner.ipynb"
            notebook.write_text("{}", encoding="utf-8")

            with self.assertRaises(REMOTE_CLI.PathGuardError) as ctx:
                REMOTE_CLI.guard_entrypoint(target.resolve(), job_dir)

            message = str(ctx.exception)
            self.assertIn("a file was expected", message)
            self.assertIn(str(notebook.resolve()), message)
            self.assertNotIn("regenerate", message.lower())

    def test_a_bare_directory_lacking_run_config_still_gets_the_generic_refusal(
        self,
    ) -> None:
        """The narrower case must not swallow the general one: a directory
        that merely LOOKS job-folder-shaped by depth, but holds neither
        `run-config.json` nor `runner.ipynb`, is not this special case."""
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            job_dir = target / "tools" / "svc" / "job-a"
            job_dir.mkdir(parents=True)
            # Deliberately empty -- no run-config.json, no runner.ipynb.

            with self.assertRaises(REMOTE_CLI.PathGuardError) as ctx:
                REMOTE_CLI.guard_entrypoint(target.resolve(), job_dir)

            message = str(ctx.exception)
            self.assertNotIn("a file was expected", message)

    def test_the_shallow_file_case_keeps_its_existing_generic_refusal(self) -> None:
        """Regression lock for `test_three_deep_tools_path_is_refused`'s own
        case: a `.ipynb` FILE one level too shallow (no job-name directory)
        is a different defect and must keep the generic message, never the
        job-folder-directory one."""
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            service_dir = target / "tools" / "svc"
            service_dir.mkdir(parents=True)
            notebook = service_dir / "runner.ipynb"
            notebook.write_text("{}", encoding="utf-8")

            with self.assertRaises(REMOTE_CLI.PathGuardError) as ctx:
                REMOTE_CLI.guard_entrypoint(target.resolve(), notebook)

            message = str(ctx.exception)
            self.assertNotIn("a file was expected", message)


class ProductForParserDerivedRemedyTests(unittest.TestCase):
    """Case C -- `product_for()`'s refusal must never name `--product` as a
    remedy unless the CALLING subcommand's own parser actually declares
    that flag. Only `submit` and `generate-job` declare `--product`;
    `status`, `distribute`, `fetch` and `reconcile` do not, yet all five
    used to reach the SAME hand-written "no explicit --product" prose
    regardless of which subcommand asked.

    Every test in this class has a reachable red: before this task,
    `product_for()` accepts no `command` keyword at all, so passing one
    raises `TypeError`, and its refusal is hand-written prose that names
    `--product` unconditionally.
    """

    def _subparser_option_strings(self, command: str) -> frozenset[str]:
        """Read `_build_parser()`'s own subparser actions directly -- never
        a hand-maintained assumption about what a subcommand declares."""
        parser = REMOTE_CLI._build_parser()
        subparsers_action = next(
            action for action in parser._actions
            if isinstance(action, REMOTE_CLI.argparse._SubParsersAction)
        )
        subparser = subparsers_action.choices[command]
        return frozenset(subparser._option_string_actions)

    def test_status_subparser_declares_no_product_flag(self) -> None:
        """Locks the fixture assumption every other test below relies on,
        read from the parser itself rather than assumed by hand."""
        self.assertNotIn("--product", self._subparser_option_strings("status"))

    def test_submit_subparser_does_declare_a_product_flag(self) -> None:
        self.assertIn("--product", self._subparser_option_strings("submit"))

    def _unresolvable_entrypoint(self, target: Path) -> Path:
        """Neither shape `product_for()` resolves: not `tools/<svc>/<job>/`
        (job-folder), not `<Name>/Notebooks/` (legacy)."""
        entrypoint = target / "random" / "foo.ipynb"
        entrypoint.parent.mkdir(parents=True)
        entrypoint.write_text("{}", encoding="utf-8")
        return entrypoint

    def test_a_status_refusal_never_cites_a_flag_status_does_not_declare(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            entrypoint = self._unresolvable_entrypoint(target)

            with self.assertRaises(REMOTE_CLI.RemoteCLIError) as ctx:
                REMOTE_CLI.product_for(target.resolve(), entrypoint, command="status")

            self.assertNotIn("--product", str(ctx.exception))

    def test_a_submit_refusal_still_names_its_own_product_override(self) -> None:
        """The remedy is derived, not merely deleted: a subcommand that
        DOES declare `--product` must keep naming it."""
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            entrypoint = self._unresolvable_entrypoint(target)

            with self.assertRaises(REMOTE_CLI.RemoteCLIError) as ctx:
                REMOTE_CLI.product_for(target.resolve(), entrypoint, command="submit")

            self.assertIn("--product", str(ctx.exception))

    def test_cmd_status_itself_reaches_the_non_misdirecting_refusal(self) -> None:
        """End-to-end at the `cmd_status` seam, not only at `product_for()`
        directly -- proving `cmd_status` actually passes its own command
        name through, not merely that `product_for()` supports the kwarg."""
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            entrypoint = self._unresolvable_entrypoint(target)

            with self.assertRaises(REMOTE_CLI.RemoteCLIError) as ctx:
                REMOTE_CLI.cmd_status(target=target, entrypoint=entrypoint)

            self.assertNotIn("--product", str(ctx.exception))



class NestedPathSerializationTests(unittest.TestCase):
    """Every command's payload becomes JSON in exactly one place -- `main()`
    -- and four of those call sites named one `Path` key by hand and assumed
    it was the only `Path` in the payload.

    That assumption already shipped a defect. `cmd_status` grew a nested
    `smoke.ledgerPath`; `main()` stringified the top-level `ledgerPath` by
    name, never reached the nested one, and `status` -- the command whose
    only job is to print -- raised `TypeError: Object of type PosixPath is
    not JSON serializable` on every invocation with empty stdout. Sixteen
    tests drove `cmd_status()`; none drove `main(["status", ...])`, so
    coverage sat on one side of the seam and the defect on the other.
    `test_the_status_command_prints_what_the_function_only_returned` is that
    command-level lock; this class is its four siblings.

    Those four carry the identical shape. None of their payloads nests a
    `Path` today -- which is exactly why all four looked fine, and why a
    test over today's flat payload would prove nothing about the class. So
    each test below injects a `Path` BELOW the top level, the way `status`
    acquired its `smoke` block, and asserts the command still exits 0 with
    that nested value rendered as a string.

    Each test drives `main([...])` -- the command -- never the `cmd_*`
    function, because the serialization under test exists nowhere else.
    """

    @contextlib.contextmanager
    def _backend_patched(self):
        """`main()` resolves a backend and constructs an adapter before it
        ever reaches the `cmd_*` function these tests replace -- the same
        three patches `test_a_job_folder_refusal_reaches_stderr_through_the_cli`
        already uses, reused rather than reinvented.
        """
        with unittest.mock.patch.object(
            REMOTE_CLI, "_load_backend_module", return_value=None
        ), unittest.mock.patch.object(
            REMOTE_CLI.ADAPTER, "resolve", return_value=FakeAdapter
        ), unittest.mock.patch.object(
            REMOTE_CLI, "_construct_adapter",
            return_value=FakeAdapter(worker_id="w1", capacity=2),
        ):
            yield

    def test_the_submit_command_in_campaign_mode_prints_a_nested_path(self) -> None:
        """`submit --unit` -- campaign mode's own `assignments[]` shape.

        `staleness` is `_job_folder_staleness()`'s own sub-dict: the exact
        kind of nested mapping `status` was carrying when it broke.
        """
        payload = {
            "assignments": [
                {
                    "worker": "w1",
                    "granted": 1,
                    "inFlightSource": None,
                    "units": ["u1"],
                    "submissionId": "s1",
                }
            ],
            "unplaced": [],
            "skipped": [],
            "ledgerPath": Path("/tmp/nowhere/ledger.jsonl"),
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
            "smoke": False,
        }

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_submit", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "submit",
                "--target", "/tmp/nowhere",
                "--entrypoint", "/tmp/nowhere/a.ipynb",
                "--backend", "fake",
                "--unit", "u1",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertIsInstance(printed["ledgerPath"], str)
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_submit_command_for_one_submission_prints_a_nested_path(self) -> None:
        """`submit` without `--unit` -- the single-submission shape, which
        reshapes the payload down to six named keys. The reshaping stays;
        only the hand-naming of the `Path` inside it goes.
        """
        payload = {
            "plan": SimpleNamespace(granted=1),
            "submission": SimpleNamespace(id="s1", worker="w1"),
            "event": {},
            "ledgerPath": Path("/tmp/nowhere/ledger.jsonl"),
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
            "smoke": False,
        }

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_submit", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "submit",
                "--target", "/tmp/nowhere",
                "--entrypoint", "/tmp/nowhere/a.ipynb",
                "--backend", "fake",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        # The reshaped keys are unchanged -- `default=str` changes HOW a
        # `Path` renders, never WHAT this command prints.
        self.assertEqual(printed["submissionId"], "s1")
        self.assertEqual(printed["worker"], "w1")
        self.assertEqual(printed["granted"], 1)
        self.assertIsInstance(printed["ledgerPath"], str)
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_fetch_command_prints_a_nested_path(self) -> None:
        """`fetch` hand-named `path` and would have missed anything below
        it, `staleness` included.
        """
        payload = {
            "verdict": "current",
            "complete": True,
            "path": Path("/tmp/nowhere/out"),
            "event": {"kind": "returned"},
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
            "arbitration": None,
        }

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_fetch", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "fetch",
                "--target", "/tmp/nowhere",
                "--entrypoint", "/tmp/nowhere/a.ipynb",
                "--submission-id", "s1",
                "--dest", "/tmp/nowhere/out",
                "--backend", "fake",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["verdict"], "current")
        self.assertTrue(printed["complete"])
        self.assertIsInstance(printed["path"], str)
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_smoke_record_command_prints_a_nested_path(self) -> None:
        """`smoke record` hand-named `smokeLedgerPath`. A `Path` inside
        `requiredEvidence` -- a sequence, not a mapping -- is just as far
        below the top level, and just as unreachable by name.

        This command resolves no backend, so it needs none of the adapter
        patches the three above do.
        """
        payload = {
            "result": "pass",
            "missing": [],
            "requiredEvidence": ["runs.jsonl", Path("/tmp/nowhere/job/shard.json")],
            "smokeLedgerPath": Path("/tmp/nowhere/smoke.jsonl"),
            "event": {},
        }

        buffer = io.StringIO()
        with unittest.mock.patch.object(
            REMOTE_CLI, "cmd_smoke_record", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "smoke", "record",
                "--job-dir", "/tmp/nowhere/job",
                "--from-artifact", "/tmp/nowhere/a.json",
                "--worker", "w1",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["result"], "pass")
        self.assertEqual(printed["missing"], [])
        self.assertIsInstance(printed["smokeLedgerPath"], str)
        self.assertIsInstance(printed["requiredEvidence"][1], str)

    def test_the_distribute_command_prints_a_nested_path(self) -> None:
        """`distribute` (2869) prints `result` whole, with no `default=str`
        net at all -- not even a hand-named single key. `status` acquired
        its nested `smoke.ledgerPath` block the same way this payload
        could acquire a nested `staleness` block: a later caller adds a
        sub-dict to `cmd_distribute`'s own return value and nobody
        revisits this print site.
        """
        payload = {
            "units": 1,
            "places": 1,
            "assigned": 1,
            "unplaced": [],
            "assignments": [
                {
                    "worker": "w1",
                    "requested": 1,
                    "cap": 2,
                    "inFlight": 0,
                    "granted": 1,
                    "inFlightSource": "list_active",
                    "units": ["u1"],
                }
            ],
            "skipped": [],
            "consentToken": "deadbeef",
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
        }

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_distribute", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "distribute",
                "--target", "/tmp/nowhere",
                "--entrypoint", "/tmp/nowhere/a.ipynb",
                "--backend", "fake",
                "--unit", "u1",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["places"], 1)
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_reconcile_command_prints_a_nested_path(self) -> None:
        """`reconcile` (2971) prints `result` whole -- same no-net shape as
        `distribute` -- after popping `arbitration` off it for stderr.
        """
        payload = {
            "orphanRemote": [],
            "orphanLocal": [],
            "resolved": [],
            "remote": {"status": "read", "reason": None},
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
            "arbitration": [],
        }

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_reconcile", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "reconcile",
                "--target", "/tmp/nowhere",
                "--entrypoint", "/tmp/nowhere/a.ipynb",
                "--worker", "w1",
                "--backend", "fake",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["remote"]["status"], "read")
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_readiness_command_prints_a_nested_path(self) -> None:
        """`readiness` (3081) prints `result` whole and resolves no
        backend at all -- it takes no `adapter` parameter, the same
        "reports and resolves nothing" discipline `status` holds.
        """
        payload = {
            "ready": False,
            "reason": "latest smoke record does not match",
            "latestSmokeRecord": None,
            "staleness": {"status": "stale", "jobFolder": Path("/tmp/nowhere/job")},
        }

        buffer = io.StringIO()
        with unittest.mock.patch.object(
            REMOTE_CLI, "cmd_readiness", return_value=payload
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "readiness",
                "--job-dir", "/tmp/nowhere/job",
                "--worker", "w1",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["ready"], False)
        self.assertIsInstance(printed["staleness"]["jobFolder"], str)

    def test_the_poll_command_prints_a_nested_value(self) -> None:
        """`poll` (2891) hand-names exactly two keys off the returned
        `Status` -- `state` and `detail` -- and `Status.__post_init__`
        only ever validates `state` against the seam's own vocabulary;
        `detail` carries whatever a backend hands back. A backend
        reporting a structured `detail` (not the plain string every
        adapter happens to send today) is exactly the same latent shape
        as `status`'s own `smoke.ledgerPath`.
        """
        status_result = SimpleNamespace(
            state="queued",
            detail={"raw": Path("/tmp/nowhere/detail")},
        )

        buffer = io.StringIO()
        with self._backend_patched(), unittest.mock.patch.object(
            REMOTE_CLI, "cmd_poll", return_value=status_result
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "poll",
                "--submission-id", "s1",
                "--backend", "fake",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["state"], "queued")
        self.assertIsInstance(printed["detail"]["raw"], str)

    def test_the_generate_job_command_prints_a_nested_path(self) -> None:
        """`generate-job` (3025) prints its own literal dict with no net
        either, and it carries `staleness` -- the exact sub-dict
        `_staleness_for()` builds and the exact shape `status` broke on
        once already, one layer up.

        `--commit` is passed explicitly so `JOBFOLDER.pin_source()`
        returns `"explicit"` without ever touching git; `generate_job`
        and `read` are mocked outright, so this drives no real job-folder
        generation and touches no adapter, backend or credential at all.
        """
        destination = Path("/tmp/nowhere/tools/fakesvc/jobx")
        job_folder = SimpleNamespace(
            run_config={"commit": "a" * 40},
            staleness={
                "status": "stale",
                "reason": None,
                "changedPaths": [Path("/tmp/nowhere/x.py")],
            },
        )

        buffer = io.StringIO()
        with unittest.mock.patch.object(
            REMOTE_CLI.JOBFOLDER, "generate_job", return_value=destination
        ), unittest.mock.patch.object(
            REMOTE_CLI.JOBFOLDER, "read", return_value=job_folder
        ), contextlib.redirect_stdout(buffer):
            code = REMOTE_CLI.main([
                "generate-job",
                "--target", "/tmp/nowhere",
                "--service", "fakesvc",
                "--job-name", "jobx",
                "--product", "P",
                "--commit", "a" * 40,
                "--repo-url", "https://example.invalid/repo.git",
                "--repo-ref", "main",
                "--run-module", "m",
                "--run-function", "f",
            ])

        self.assertEqual(code, 0)
        printed = json.loads(buffer.getvalue())
        self.assertEqual(printed["commitSource"], "explicit")
        self.assertIsInstance(printed["staleness"]["changedPaths"][0], str)


class PushSurfaceHookTests(unittest.TestCase):
    """`scripts/hooks/refuse_offpath_push.py` (design §5): a tripwire, not
    a gate. The load-bearing precondition is `_verify_launch_authorization()`
    (`AuthorizationGateTests` above); this class exercises only the residue
    that precondition cannot see -- a launch that never calls `submit` at
    all -- and the script's own fail-open discipline for everything it
    cannot parse.

    Committed as an inert artifact, deliberately never wired into
    `.claude/settings.json` by this change: turning it on is a decision
    for a human, not this script's own existence.
    """

    def setUp(self) -> None:
        # `_load_push_surfaces()` execs every adapter module to read its
        # declared constant — and colab.py's own bottom line registers
        # itself again, so the scan REPLACES the shared registry's entry
        # for "colab" with a second copy's class. Harmless in the hook's
        # own short-lived process; not harmless here, where this suite
        # runs in one process and `ColabAdapterSeamTests` asserts the
        # ORIGINAL copy stays registered. Snapshot before every test in
        # this class, restore after, so the scans leave no trace on
        # global state.
        self._registry_snapshots = {
            name: dict(getattr(ADAPTER, name))
            for name in (
                "_REGISTRY",
                "_METADATA_REGISTRY",
                "_DEFAULT_ACCELERATOR_REGISTRY",
                "_DECLARED_CAPACITY_REGISTRY",
            )
        }

    def tearDown(self) -> None:
        for name, snapshot in self._registry_snapshots.items():
            registry = getattr(ADAPTER, name)
            registry.clear()
            registry.update(snapshot)

    def test_push_surfaces_are_read_from_the_real_adapter_not_hardcoded(self) -> None:
        surfaces = PUSH_SURFACE_HOOK._load_push_surfaces()
        self.assertIn("kernels_push", surfaces)
        self.assertIn("kaggle_driver.py", surfaces)

    def test_a_command_naming_kernels_push_without_remote_cli_is_flagged(self) -> None:
        matched = PUSH_SURFACE_HOOK.offpath_push(
            "python3 adapters/kaggle_driver.py push --dir tools/kaggle/search-a",
            ("kaggle_driver.py", "kernels_push"),
        )
        self.assertEqual(matched, "kaggle_driver.py")

    def test_a_command_that_also_invokes_remote_cli_is_never_flagged(self) -> None:
        """The predicate is conjunctive, not a bare substring search: a
        command that legitimately runs `remote_cli.py submit` may well
        mention a push-surface token (in a comment, a log path, a
        docstring test invocation) without that being the off-path shape
        this hook exists to catch.
        """
        matched = PUSH_SURFACE_HOOK.offpath_push(
            "python3 skills/remote-execution/scripts/remote_cli.py "
            "submit --target x --entrypoint y # uses kernels_push internally",
            ("kaggle_driver.py", "kernels_push"),
        )
        self.assertIsNone(matched)

    def test_a_command_naming_neither_is_never_flagged(self) -> None:
        matched = PUSH_SURFACE_HOOK.offpath_push(
            "git status", ("kaggle_driver.py", "kernels_push"),
        )
        self.assertIsNone(matched)

    # -- what it explicitly does NOT do: read a job's mode ----------------

    def test_the_predicate_reads_no_job_folder_and_no_mode(self) -> None:
        """Design §5's own recorded rejection: `mode=smoke` is a
        `submit`-time argv flag, never a job-folder property readable
        before submission. `offpath_push()` takes only a command string
        and a tuple of tokens -- no target, no job directory, no mode --
        so there is no parameter this predicate COULD read a mode from.
        """
        import inspect

        parameters = list(inspect.signature(PUSH_SURFACE_HOOK.offpath_push).parameters)
        self.assertEqual(parameters, ["command", "push_surfaces"])

    # -- the PreToolUse contract: refuse, or stay silent -------------------

    def _run_main(self, payload: object) -> tuple[int, str]:
        stdin = io.StringIO(json.dumps(payload) if not isinstance(payload, str) else payload)
        stderr = io.StringIO()
        with unittest.mock.patch.object(sys, "stdin", stdin), \
                contextlib.redirect_stderr(stderr):
            code = PUSH_SURFACE_HOOK.main([])
        return code, stderr.getvalue()

    def test_main_refuses_an_offpath_push_command_with_exit_2(self) -> None:
        code, stderr = self._run_main({
            "tool_name": "Bash",
            "tool_input": {
                "command": "python3 adapters/kaggle_driver.py push --dir x",
            },
        })
        self.assertEqual(code, 2)
        self.assertIn("kaggle_driver.py", stderr)
        self.assertIn("remote_cli.py", stderr)

    def test_main_stays_silent_on_a_command_routed_through_submit(self) -> None:
        code, stderr = self._run_main({
            "tool_name": "Bash",
            "tool_input": {
                "command": "python3 skills/remote-execution/scripts/"
                           "remote_cli.py submit --target x --entrypoint y",
            },
        })
        self.assertEqual(code, 0)
        self.assertEqual(stderr, "")

    def test_main_stays_silent_on_an_unrelated_command(self) -> None:
        code, stderr = self._run_main({
            "tool_name": "Bash",
            "tool_input": {"command": "git status"},
        })
        self.assertEqual(code, 0)
        self.assertEqual(stderr, "")

    def test_main_never_refuses_on_malformed_input_it_cannot_parse(self) -> None:
        """A tripwire that cannot parse its own input refuses NOTHING --
        it never fails closed onto a command it never actually read.
        """
        code, stderr = self._run_main("not valid json at all {{{")
        self.assertEqual(code, 0)
        self.assertEqual(stderr, "")

    def test_main_stays_silent_on_a_non_bash_payload_with_no_command_key(self) -> None:
        code, stderr = self._run_main({"tool_name": "Read", "tool_input": {"file_path": "x"}})
        self.assertEqual(code, 0)
        self.assertEqual(stderr, "")


class ObjectiveFlowTests(unittest.TestCase):
    """The north: why this skill was invoked and where it has to arrive."""

    def test_there_is_one_place_a_refusal_reaches_a_reader(self) -> None:
        """It did not exist. Fourteen call sites each printed the error and
        returned 1, so there was nowhere to attach what every refusal should
        carry and nothing could hold them to agreeing. This pins the single
        place: the only `print(f"error: ...")` left is the one inside it.
        """
        source = REMOTE_CLI_SCRIPT.read_text(encoding="utf-8")
        self.assertEqual(
            source.count('print(f"error: {exc}", file=sys.stderr)'), 1,
            "a refusal prints outside `_refused`, so it reaches a reader "
            "without the north the others carry")
        self.assertIn('"objective": OBJECTIVE_FLOW', source)

    def test_a_refusal_carries_it(self) -> None:
        """Asserted through the function itself rather than by reading the
        source twice: what a reader receives is what this returns."""
        buffer = io.StringIO()
        with contextlib.redirect_stderr(buffer):
            status = REMOTE_CLI._refused(RuntimeError("something refused"))
        written = buffer.getvalue()
        self.assertEqual(status, 1, "the exit status is unchanged")
        self.assertIn("something refused", written)
        self.assertIn(REMOTE_CLI.OBJECTIVE_FLOW["purpose"], written)

    def test_it_is_declared_and_not_derived(self) -> None:
        """Invariant on purpose: it has to read the same on a repository that
        has submitted nothing as on one mid-campaign."""
        flow = REMOTE_CLI.OBJECTIVE_FLOW
        self.assertEqual([s["stage"] for s in flow["stages"]],
                         ["reachable", "wire", "authorized", "sent", "returned"])
        for stage in flow["stages"]:
            self.assertTrue(stage["establishes"] and stage["behindWhen"])

    def test_reconcile_is_a_repair_that_returns_and_not_a_stage(self) -> None:
        """Said explicitly because without it `drift` reads as having lost the
        work rather than as a detour."""
        flow = REMOTE_CLI.OBJECTIVE_FLOW
        self.assertNotIn("reconcile", [s["stage"] for s in flow["stages"]])
        repair = flow["repairs"][0]
        self.assertEqual(repair["act"], "reconcile")
        self.assertEqual(repair["returnsTo"], "sent")

    def test_arrival_is_the_result_back_and_not_the_submission_accepted(self) -> None:
        """The distinction this whole skill turns on: a submission the service
        took is a receipt, and a receipt is not a measurement."""
        self.assertIn("verified", REMOTE_CLI.OBJECTIVE_FLOW["arrival"])
        self.assertTrue(REMOTE_CLI.OBJECTIVE_FLOW["humanStops"])

    def test_the_doctrine_states_the_same_stages(self) -> None:
        """Held equal to the data, scoped to the section's own table -- a
        whole-document search finds these words everywhere and would stay
        green through a renamed row."""
        skill = SKILL_MD.read_text(encoding="utf-8")
        start = skill.index("## The objective flow")
        table = skill[start:skill.index("**Arrival:**", start)]
        rows = [line for line in table.splitlines() if line.startswith("| `")]
        self.assertEqual(
            [line.split("`")[1] for line in rows],
            [stage["stage"] for stage in REMOTE_CLI.OBJECTIVE_FLOW["stages"]])
        self.assertIn(REMOTE_CLI.OBJECTIVE_FLOW["arrival"], skill)


class AnnotatedModuleConstantFoldTests(unittest.TestCase):
    """`NAME: type = value` is `ast.AnnAssign`, and `_fold_module_constants()`
    walked only `ast.Assign`.

    An annotation changes nothing about what a constant is worth, so a chain
    with one annotated link in it has to fold to exactly what the same chain
    spelled flat folds to. It did not: the annotated link never entered the
    table, every constant built on top of it then failed to fold as well, and
    the read through them left the path table entirely -- so an undeclared
    read that the flat spelling refuses generation over went unreported.

    Both forms are exercised in every test here and asserted to AGREE. Pinning
    only the annotated one would pass just as well against a reader that had
    stopped reading the flat one.
    """

    CHAIN = (
        "from pathlib import Path\n\n"
        "{repository}\n"
        '{product}\n'
        'RECORD = PRODUCT / "Results" / "ledger.json"\n\n\n'
        "def ledger_on_record():\n"
        "    return RECORD.read_text(encoding='utf-8')\n"
    )

    FLAT_REPOSITORY = "REPOSITORY = Path(__file__).resolve().parents[2]"
    ANNOTATED_REPOSITORY = "REPOSITORY: Path = Path(__file__).resolve().parents[2]"
    FLAT_PRODUCT = 'PRODUCT = REPOSITORY / "product-out"'
    ANNOTATED_PRODUCT = 'PRODUCT: Path = REPOSITORY / "product-out"'

    def _resolve(self, repository, product):
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp)
            path = target / "src" / "pkg_z" / "settings.py"
            path.parent.mkdir(parents=True)
            path.write_text(
                self.CHAIN.format(repository=repository, product=product),
                encoding="utf-8",
            )
            return JOBFOLDER.resolve_clone_paths(
                target, ["pkg_z.settings"], ["src/pkg_z"]
            )

    def test_an_annotated_link_folds_to_what_the_flat_chain_folds_to(self):
        """The finding: one annotated link in the middle used to drop the
        whole resolved path off the report, and an undeclared read with it."""
        flat = self._resolve(self.FLAT_REPOSITORY, self.FLAT_PRODUCT)
        annotated = self._resolve(self.ANNOTATED_REPOSITORY, self.ANNOTATED_PRODUCT)

        self.assertEqual(
            flat["computedReadsNotDeclared"],
            ["product-out/Results/ledger.json"],
        )
        self.assertEqual(annotated["computedReadsNotDeclared"],
                         flat["computedReadsNotDeclared"])
        self.assertEqual(annotated["unresolvedReads"], flat["unresolvedReads"])

    def test_a_single_annotated_link_is_enough_to_break_the_chain(self):
        """Isolates the mechanism: only `REPOSITORY` is annotated, and both
        constants built on top of it are spelled exactly as the flat chain
        spells them. Everything downstream of one unread link is unread."""
        mixed = self._resolve(self.ANNOTATED_REPOSITORY, self.FLAT_PRODUCT)
        self.assertEqual(
            mixed["computedReadsNotDeclared"],
            ["product-out/Results/ledger.json"],
        )

    def test_a_bare_annotation_binds_nothing_and_is_not_a_second_assignment(self):
        """`NAME: Path` with no value assigns nothing, so it must neither
        enter the table nor evict the real assignment beside it -- a name
        assigned twice is dropped, and this was never assigned once.

        The bare annotation is written AFTER the real assignment on purpose:
        before it, a reader that mishandled it would still recover, and the
        test would pass over an implementation that treats the annotation as
        an assignment. After it, mishandling costs the whole chain.
        """
        result = self._resolve(
            self.FLAT_REPOSITORY + "\nREPOSITORY: Path", self.FLAT_PRODUCT)
        self.assertEqual(
            result["computedReadsNotDeclared"],
            ["product-out/Results/ledger.json"],
        )

    def test_an_annotated_name_assigned_twice_is_still_dropped(self):
        """The existing discipline, held across the new form: two assignments
        mean the first fold cannot be trusted as the name's one true value,
        and admitting annotations must not open a way around that.

        The second assignment resolves somewhere else that is still INSIDE the
        target, so last-wins would report a different path rather than no path
        -- an empty result here means the name was dropped, not that the read
        fell outside the repository and was filtered away.
        """
        result = self._resolve(
            self.ANNOTATED_REPOSITORY
            + "\nREPOSITORY = Path(__file__).resolve().parents[1]",
            self.FLAT_PRODUCT)
        self.assertEqual(result["computedReadsNotDeclared"], [])


class ColabAdapterSeamTests(unittest.TestCase):
    """`adapters/colab.py` — the second backend's own file, slice S1's seam
    surface: registration, the static worker, session listing, cancel, and
    the explicit refusals standing in for everything the session-lifecycle
    slice (S2) has not landed yet.

    No test here reaches the network or a real Colab account: every
    subprocess call goes to a fake `colab` executable this class writes
    into a temp directory and hands over by path (`colab_executable=`).
    The session-line fixtures are the shapes measured live in spike S0.
    """

    def _fake_colab(
        self,
        tmp: str,
        *,
        stdout: str = "",
        stderr: str = "",
        exit_code: int = 0,
        record: bool = False,
    ) -> tuple[str, Path | None]:
        """A fake `colab` executable, written into `tmp` and handed back by
        path — never a PATH entry, so no resolution can ever reach a real
        installation. `record=True` also returns the log path its argv
        lands in, one argument per line.
        """
        script = Path(tmp) / "colab"
        log = Path(tmp) / "argv.txt"
        lines = ["#!/usr/bin/env python3", "import sys"]
        if record:
            lines.append("open(%r, 'w').write('\\n'.join(sys.argv[1:]))" % str(log))
        lines.append("sys.stdout.write(%r)" % stdout)
        lines.append("sys.stderr.write(%r)" % stderr)
        lines.append("raise SystemExit(%d)" % exit_code)
        script.write_text("\n".join(lines) + "\n", encoding="utf-8")
        script.chmod(0o755)
        return str(script), (log if record else None)

    def test_colab_adapter_satisfies_the_abc(self) -> None:
        self.assertIsInstance(COLAB.ColabAdapter(), ADAPTER.Adapter)

    def test_colab_is_registered_under_its_own_name_and_silent_elsewhere(self) -> None:
        """Registration only — and the silence D6 requires: no metadata
        assembler. The accelerator default is NOT silent: a job generated
        with no accelerator flags must still ask Colab for a GPU, exactly
        as every Kaggle push does, or it runs on CPU without a word. The declared-capacity
        reporter is NOT silent (S5/SD21): the engine's launch-proposal
        publisher reads that registry to compose a `launch` action, and a
        miss there left every colab gate chain unmintable — its answer is
        the same constant `workers()` already declares, never a guess.
        """
        self.assertIs(ADAPTER.resolve("colab"), COLAB.ColabAdapter)
        with self.assertRaises(KeyError):
            ADAPTER.resolve_metadata("colab")
        self.assertIsNotNone(ADAPTER.resolve_declared_capacity("colab"))

    def test_colab_registers_a_gpu_default_that_maps_to_a_variant(self) -> None:
        """A from-zero Colab job asks for a GPU: the registered default is
        one `cuda` architecture the variant table maps to `--gpu`, so
        `submit` requests that machine and the VM-side gate refuses a CPU
        runtime instead of running on it.
        """
        provider = ADAPTER.resolve_default_accelerator("colab")
        self.assertIsNotNone(provider, "adapters/colab.py must register a default")
        kind, architectures = provider()
        self.assertEqual(kind, "cuda")
        self.assertEqual(tuple(architectures), COLAB.COLAB_ACCELERATOR_ARCHITECTURES)
        self.assertEqual(len(architectures), 1)
        variant = COLAB.ColabAdapter()._accelerator_variant(
            {"kind": kind, "architectures": list(architectures)})
        self.assertEqual(variant, "T4")

    def test_colab_declared_capacity_is_the_static_worker_figure(self) -> None:
        """The declared-capacity channel (S5/SD21) answers the same static
        fact `workers()` already declares — patching the subprocess
        boundary to explode proves the reporter reaches no child, the
        property the engine's offer path depends on.
        """
        reporter = ADAPTER.resolve_declared_capacity("colab")
        self.assertIsNotNone(reporter)
        with unittest.mock.patch.object(
            COLAB.subprocess, "run", side_effect=AssertionError("no subprocess")
        ):
            self.assertEqual(reporter(), (1, 1))

    def test_colab_declares_its_own_push_surface_for_the_tripwire(self) -> None:
        self.assertEqual(
            COLAB.PUSH_SURFACE,
            ("colab new", "colab exec", "colab run", "colab upload"),
        )

    def test_workers_are_static_and_never_shell_out(self) -> None:
        """`workers()` answers from constants: patching the subprocess
        boundary to explode proves the method reaches no child at all, the
        same guarantee the ledger fallback in `packer.plan()` depends on.
        """
        adapter = COLAB.ColabAdapter()
        with unittest.mock.patch.object(
            COLAB.subprocess, "run", side_effect=AssertionError("no subprocess")
        ):
            workers = adapter.workers()
        self.assertEqual([(w.id, w.capacity) for w in workers], [("colab", 1)])

    def test_packer_plans_and_selects_the_static_colab_worker_through_the_seam(
        self,
    ) -> None:
        """Slice S1's own done-when, through `packer`'s real entry points:
        one live `list_active()` read (the fake executable, never the
        network) refines the ledger estimate, and the static capacity-1
        worker yields exactly one place to both `plan()` and `select()`.
        """
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(
                tmp, stdout="[colab] No active sessions found on server.\n"
            )
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            plan = PACKER.plan(
                adapter=adapter,
                worker_id="colab",
                requested=3,
                ledger_lines=[],
                live_digest="d" * 64,
            )
            self.assertEqual(
                (plan.cap, plan.granted, plan.in_flight_source),
                (1, 1, "list_active"),
            )
            selected = PACKER.select(
                adapter=adapter,
                requested=3,
                ledger_lines=[],
                live_digest="d" * 64,
            )
            self.assertEqual(selected.worker, "colab")
            self.assertEqual(selected.granted, 1)

    def test_list_active_claims_only_prefixed_named_sessions(self) -> None:
        """One listing, three cases in one fixture: an orphan (`[?]`) is
        skipped — it has no name to address — a foreign tool's session is
        skipped (the CLI lists the ACCOUNT, not this skill), and both
        prefixed names come back as `<worker>/<session>` ids.
        """
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(
                tmp,
                stdout=(
                    "[?] m-s-orphan | Hardware: CPU | Variant: DEFAULT\n"
                    "[psmith-a-01234567] m-1 | Hardware: CPU | Variant: DEFAULT\n"
                    "[someone-elses-tool] m-2 | Hardware: GPU | Variant: GPU\n"
                    "\n"
                    "[psmith-b-89abcdef] m-3 | Hardware: T4 | Variant: GPU\n"
                ),
            )
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            self.assertEqual(
                adapter.list_active("colab"),
                ["colab/psmith-a-01234567", "colab/psmith-b-89abcdef"],
            )

    def test_list_active_reads_the_no_sessions_message_as_empty(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(
                tmp, stdout="[colab] No active sessions found on server.\n"
            )
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            self.assertEqual(adapter.list_active("colab"), [])

    def test_list_active_refuses_a_nonzero_exit(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(tmp, stderr="boom\n", exit_code=1)
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                adapter.list_active("colab")
            self.assertIn("boom", str(ctx.exception))

    def test_cancel_stops_by_session_name(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            exe, log = self._fake_colab(
                tmp, stdout="[colab] Session terminated.\n", record=True
            )
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            self.assertIsNone(adapter.cancel("colab/psmith-a-01234567"))
            assert log is not None
            self.assertEqual(
                log.read_text(encoding="utf-8").splitlines(),
                ["stop", "-s", "psmith-a-01234567"],
            )

    def test_cancel_treats_not_found_as_already_gone(self) -> None:
        """The measured S0 shape: `stop` on an unknown session prints
        `Session 'x' not found.` and exits 0. Output is the signal here,
        never the exit code, so an already-released session is a no-op
        rather than a fabricated failure.
        """
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(
                tmp, stdout="[colab] Session 'psmith-x' not found.\n"
            )
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            self.assertIsNone(adapter.cancel("colab/psmith-x"))

    def test_cancel_refuses_a_generic_failure(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            exe, _ = self._fake_colab(tmp, stderr="kaboom\n", exit_code=1)
            adapter = COLAB.ColabAdapter(colab_executable=exe)
            with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                adapter.cancel("colab/psmith-x")
            self.assertIn("kaboom", str(ctx.exception))

    def test_cancel_refuses_a_submission_id_without_a_session_name(self) -> None:
        adapter = COLAB.ColabAdapter()
        with self.assertRaises(COLAB.ColabAdapterError):
            adapter.cancel("colab")

    def test_missing_cli_refuses_with_the_install_remedy(self) -> None:
        adapter = COLAB.ColabAdapter(colab_executable="/definitely/not/here/colab")
        with self.assertRaises(COLAB.ColabAdapterError) as ctx:
            adapter.list_active("colab")
        self.assertIn("google-colab-cli", str(ctx.exception))

    def test_a_process_without_home_is_refused(self) -> None:
        """`HOME` carries the CLI's own credential lookup — a child
        forwarded without one would fail authentication for a reason no
        caller could read, so the refusal happens here instead.
        """
        adapter = COLAB.ColabAdapter()
        with unittest.mock.patch.dict(COLAB.os.environ, {}, clear=False):
            COLAB.os.environ.pop("HOME", None)
            with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                adapter._env_for()
        self.assertIn("HOME", str(ctx.exception))

    def test_the_lifecycle_operations_are_now_wired(self) -> None:
        """The S1 boundary this class policed is gone: slice S2 replaced
        the refusals with the real lifecycle. What remains here is the
        cheap structural assertion — the three operations are still
        *reachable* without a live service from this seam surface, and
        the deep behavior is `ColabSessionLifecycleTests`' own subject,
        driven through the stateful fake CLI.
        """
        adapter = COLAB.ColabAdapter()
        self.assertTrue(callable(adapter.submit))
        self.assertTrue(callable(adapter.poll))
        self.assertTrue(callable(adapter.fetch))
        with self.assertRaises(COLAB.ColabAdapterError):
            adapter.submit(ADAPTER.Job(entrypoint=Path("/nonexistent/runner.ipynb"),
                                       run_config={}, worker="colab"))
        with self.assertRaises(COLAB.ColabAdapterError):
            adapter.poll("colab/not-a-name-this-adapter-issues")
        with tempfile.TemporaryDirectory() as tmp:
            with self.assertRaises(COLAB.ColabAdapterError):
                adapter.fetch("colab/not-a-name-this-adapter-issues", Path(tmp))


class ColabGenerateJobUnionTests(unittest.TestCase):
    """`jobfolder.generate_job()`'s union-of-registries rule (D11) — a
    service known to EITHER registry is legal — and the front-door path a
    real `generate-job --service colab` invocation takes: a two-file job
    folder for the adapter that registers no metadata assembler, a by-name
    refusal for a service known to neither registry, and the pre-existing
    metadata-only shape left exactly as it was.
    """

    def setUp(self) -> None:
        # Same seam as `GenerateJobTests`: this class is not exercising the
        # pin preconditions, so the whole-precondition function is stubbed
        # rather than each condition's own network probe.
        patcher = unittest.mock.patch.object(
            JOBFOLDER, "verify_pin_preconditions", return_value=None
        )
        patcher.start()
        self.addCleanup(patcher.stop)

    def _fixture_assets(self, tmp: str) -> tuple[Path, Path]:
        bootstrap = Path(tmp) / "fixture_bootstrap.py"
        invoke = Path(tmp) / "fixture_invoke.py"
        bootstrap.write_text("# fixture bootstrap cell\nprint('cell-0')\n", encoding="utf-8")
        invoke.write_text("# fixture invoke cell\nprint('cell-1')\n", encoding="utf-8")
        return bootstrap, invoke

    def _ensure_source_tree(self, target: Path) -> None:
        harness = target / "src" / "FEM_TOLLA_Benchmark" / "harness.py"
        if not harness.exists():
            harness.parent.mkdir(parents=True, exist_ok=True)
            harness.write_text("def campaign(*args, **kwargs):\n    pass\n", encoding="utf-8")

    def _generate(self, tmp: str, target: Path, *, service: str) -> Path:
        bootstrap, invoke = self._fixture_assets(tmp)
        self._ensure_source_tree(target)
        return JOBFOLDER.generate_job(
            target=target,
            service=service,
            job_name="search-a",
            product="FEM-TOLLA",
            commit="a" * 40,
            repo_url="https://example.invalid/repo.git",
            repo_ref="main",
            clone_paths=["src/FEM_TOLLA_Benchmark"],
            run_module="FEM_TOLLA_Benchmark.harness",
            run_function="campaign",
            bootstrap_asset=bootstrap,
            invoke_asset=invoke,
        )

    def test_an_adapter_without_a_metadata_assembler_writes_two_files(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            job_dir = self._generate(tmp, target, service="colab")
            self.assertEqual(
                sorted(p.name for p in job_dir.iterdir()),
                ["run-config.json", "runner.ipynb"],
            )

    def test_a_service_unknown_to_both_registries_refuses_by_name(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            with self.assertRaises(JOBFOLDER.JobFolderError) as ctx:
                self._generate(tmp, target, service="nowhere-registered-service-s1")
            message = str(ctx.exception)
            self.assertIn("nowhere-registered-service-s1", message)
            self.assertIn("no adapter and no metadata assembler", message)

    def test_a_metadata_only_service_still_writes_its_metadata_file(self) -> None:
        service = f"metadata-only-fixture-{os.getpid()}"
        ADAPTER.register_metadata(
            service, lambda run_config: ("fake-metadata.json", json.dumps({"ok": True}))
        )
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "repo"
            target.mkdir()
            job_dir = self._generate(tmp, target, service=service)
            self.assertEqual(
                sorted(p.name for p in job_dir.iterdir()),
                ["fake-metadata.json", "run-config.json", "runner.ipynb"],
            )

    def test_generate_job_service_colab_through_the_real_cli(self) -> None:
        """The front-door proof, through the CLI's own side-loader: a real
        `remote_cli.py generate-job --service colab` invocation plants the
        adapter module in a fresh process, clears the union rule, and
        writes exactly the two files the adapter's shape owes. Modeled on
        `test_generate_job_reaches_the_assembler_its_service_names`.
        """
        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            origin = root / "origin.git"
            subprocess.run(["git", "init", "-q", "--bare", str(origin)], check=True)
            target = root / "target"
            subprocess.run(["git", "init", "-q", str(target)], check=True)
            package = target / "src" / "product"
            package.mkdir(parents=True)
            (package / "__init__.py").write_text("", encoding="utf-8")
            (package / "harness.py").write_text(
                "def run():\n    return {}\n", encoding="utf-8")
            git = ["git", "-C", str(target),
                   "-c", "user.email=t@t", "-c", "user.name=t"]
            subprocess.run([*git, "add", "-A"], check=True)
            subprocess.run([*git, "commit", "-q", "-m", "seed"], check=True)
            subprocess.run([*git, "remote", "add", "origin", str(origin)], check=True)
            subprocess.run([*git, "push", "-q", "origin", "HEAD:refs/heads/main"],
                           check=True)
            commit = subprocess.run([*git, "rev-parse", "HEAD"], capture_output=True,
                                    text=True, check=True).stdout.strip()
            completed = subprocess.run(
                [sys.executable, str(REMOTE_CLI_SCRIPT), "generate-job",
                 "--target", str(target), "--service", "colab",
                 "--job-name", "probe-job", "--product", "Product",
                 "--commit", commit,
                 "--repo-url", str(origin),
                 "--repo-ref", "main",
                 "--clone-path", "src/product",
                 "--run-module", "product.harness", "--run-function", "run"],
                capture_output=True, text=True, cwd=str(target),
            )
            output = completed.stdout + completed.stderr
            self.assertEqual(completed.returncode, 0, output)
            job_dir = target / "tools" / "colab" / "probe-job"
            self.assertEqual(
                sorted(p.name for p in job_dir.iterdir()),
                ["run-config.json", "runner.ipynb"],
            )


# ----------------------------------------------------------------------
# Slice S2 — the Colab session lifecycle, driven through a stateful fake
# `colab` executable. No test below reaches the network or a real Colab
# account: the fake serves the CLI's own bookkeeping (new / sessions /
# status / stop / install), performs uploads and downloads as real file
# copies against the adapter's injected `remote_root`, and runs every
# `exec -f <file>` for real with this interpreter — so the REAL rendered
# templates (launch, read_state, the inline mkdir/probe helpers) execute
# offline, and the round-trip test even runs a real notebook through the
# real `executor.py` with the venv's own nbclient.
# ----------------------------------------------------------------------

_FAKE_COLAB_SOURCE = r'''#!/usr/bin/env python
"""A stateful fake of the `colab` CLI, written per test by the forge
suite. Scenario knobs arrive as JSON in state/scenario.json; every
invocation's argv is appended to state/invocations.jsonl."""
import json
import shutil
import subprocess
import sys
import time
from pathlib import Path

STATE = Path(__STATE__)
REMOTE_ROOT = Path(__REMOTE_ROOT__)
SCENARIO_PATH = STATE / "scenario.json"
SESSIONS_PATH = STATE / "sessions.json"
INVOCATIONS = STATE / "invocations.jsonl"
INSTALLED = STATE / "installed.json"
PROBE_NAME = "dependency-probe.py"
PROBE_PACKAGES = ("nbclient", "nbformat", "jupyter_client")


def scenario():
    if SCENARIO_PATH.is_file():
        return json.loads(SCENARIO_PATH.read_text(encoding="utf-8"))
    return {}


def sessions():
    if SESSIONS_PATH.is_file():
        return json.loads(SESSIONS_PATH.read_text(encoding="utf-8"))
    return {}


def save_sessions(data):
    SESSIONS_PATH.write_text(json.dumps(data), encoding="utf-8")


def parse(argv):
    options = {}
    positionals = []
    index = 1
    while index < len(argv):
        token = argv[index]
        if token in ("-s", "--session"):
            options["session"] = argv[index + 1]
            index += 2
            continue
        if token in ("-f", "--file"):
            options["file"] = argv[index + 1]
            index += 2
            continue
        if token == "--timeout":
            options["timeout"] = argv[index + 1]
            index += 2
            continue
        positionals.append(token)
        index += 1
    return options, positionals


def main():
    argv = sys.argv[1:]
    with INVOCATIONS.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(argv) + "\n")
    data = scenario()
    command = argv[0] if argv else ""
    options, positionals = parse(argv)
    name = options.get("session", "")

    if command == "new":
        if data.get("new_fail"):
            sys.stderr.write(data.get("new_stderr", "new failed\n"))
            return 1
        sys.stdout.write("[colab] Creating session %r...\n" % name)
        if data.get("new_no_ready"):
            return 0
        bookkeeping = sessions()
        bookkeeping[name] = {"endpoint": "m-fake-%d" % (len(bookkeeping) + 1)}
        save_sessions(bookkeeping)
        sys.stdout.write("[colab] Session READY.\n")
        return 0

    if command == "sessions":
        bookkeeping = sessions()
        for line in data.get("sessions_extra", []):
            sys.stdout.write(line + "\n")
        for key, record in bookkeeping.items():
            sys.stdout.write(
                "[%s] %s | Hardware: CPU | Variant: DEFAULT\n"
                % (key, record["endpoint"])
            )
        if not bookkeeping and not data.get("sessions_extra"):
            sys.stdout.write("[colab] No active sessions found on server.\n")
        return 0

    if command == "status":
        bookkeeping = sessions()
        if data.get("status_not_found") or name not in bookkeeping:
            sys.stdout.write("[colab] Session %r not found.\n" % name)
            return 0
        sys.stdout.write(
            "[%s] %s | Hardware: CPU | Variant: DEFAULT | Status: IDLE\n"
            % (name, bookkeeping[name]["endpoint"])
        )
        return 0

    if command == "stop":
        bookkeeping = sessions()
        if name not in bookkeeping:
            sys.stdout.write("[colab] Session %r not found.\n" % name)
            return 0
        del bookkeeping[name]
        save_sessions(bookkeeping)
        sys.stdout.write("[colab] Stopping session %r...\n" % name)
        sys.stdout.write("[colab] Session terminated.\n")
        return 0

    if command == "exec":
        source = Path(options.get("file", ""))
        override = (data.get("exec") or {}).get(source.name)
        if override is not None:
            if override.get("sleep"):
                time.sleep(override["sleep"])
            sys.stdout.write(override.get("stdout", ""))
            sys.stderr.write(override.get("stderr", ""))
            return int(override.get("exit", 0))
        if source.name == PROBE_NAME and "probe_missing" in data:
            installed = []
            if INSTALLED.is_file():
                installed = json.loads(INSTALLED.read_text(encoding="utf-8"))
            still = [pkg for pkg in data["probe_missing"] if pkg not in installed]
            payload = {
                pkg: (None if pkg in still else "0.0.0") for pkg in PROBE_PACKAGES
            }
            sys.stdout.write(json.dumps(payload) + "\n")
            return 0
        if source.name in data.get("hang", []):
            time.sleep(60)
        if source.name in data.get("transport_once", []):
            marker = STATE / ("transport-%s" % source.name)
            if not marker.exists():
                marker.write_text("used", encoding="utf-8")
                sys.stderr.write("RuntimeError: Connection was lost.\n")
                return 1
        completed = subprocess.run(
            [sys.executable, str(source)], capture_output=True, text=True
        )
        sys.stdout.write(completed.stdout)
        sys.stderr.write(completed.stderr)
        return completed.returncode

    if command == "upload":
        local = Path(positionals[0])
        remote = Path(positionals[1])
        if data.get("upload_fail") == local.name:
            sys.stderr.write("Upload failed: injected\n")
            return 1
        if not remote.parent.is_dir():
            sys.stderr.write("Upload failed: no such directory %s\n" % remote.parent)
            return 1
        shutil.copy(str(local), str(remote))
        sys.stdout.write("[colab] Uploaded %r to %r\n" % (str(local), str(remote)))
        return 0

    if command == "download":
        remote = Path(positionals[0])
        local = Path(positionals[1])
        if data.get("download_missing") == remote.name or not remote.is_file():
            sys.stdout.write(
                "[colab] Download failed: File or directory not found: %s\n" % remote
            )
            return 1
        local.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy(str(remote), str(local))
        sys.stdout.write("[colab] Downloaded %r to %r\n" % (str(remote), str(local)))
        return 0

    if command == "install":
        if data.get("install_fail"):
            sys.stderr.write("install failed: injected\n")
            return 1
        if not data.get("install_no_effect"):
            INSTALLED.write_text(json.dumps(positionals), encoding="utf-8")
        sys.stdout.write("[colab] Install complete.\n")
        return 0

    if command == "keep-alive":
        return 0

    sys.stderr.write("fake colab: unknown command %r\n" % command)
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
'''


class _ColabCLISimulator:
    """See the block comment above `_FAKE_COLAB_SOURCE`."""

    def __init__(self, tmp: str) -> None:
        root = Path(tmp) / "colab-sim"
        self.state = root / "state"
        self.state.mkdir(parents=True)
        self.remote_root = root / "content" / ".psmith"
        self.remote_root.mkdir(parents=True)
        self.executable = root / "colab"
        source = _FAKE_COLAB_SOURCE.replace(
            "#!/usr/bin/env python\n", "#!%s\n" % sys.executable, 1
        )
        source = source.replace("__STATE__", repr(str(self.state)))
        source = source.replace("__REMOTE_ROOT__", repr(str(self.remote_root)))
        self.executable.write_text(source, encoding="utf-8")
        self.executable.chmod(0o755)

    def scenario(self, **knobs: object) -> None:
        (self.state / "scenario.json").write_text(json.dumps(knobs), encoding="utf-8")

    def seed_session(self, name: str, endpoint: str = "m-fake-1") -> None:
        (self.state / "sessions.json").write_text(
            json.dumps({name: {"endpoint": endpoint}}), encoding="utf-8"
        )

    def sessions_on_sim(self) -> dict:
        path = self.state / "sessions.json"
        return json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}

    def session_dir(self, name: str) -> Path:
        return self.remote_root / name

    def invocations(self) -> list[list[str]]:
        path = self.state / "invocations.jsonl"
        if not path.is_file():
            return []
        return [
            json.loads(line) for line in path.read_text(encoding="utf-8").splitlines()
        ]

    def subcommands(self) -> list[str]:
        return [tokens[0] for tokens in self.invocations()]


def _colab_trivial_notebook() -> dict:
    return {
        "cells": [
            {
                "cell_type": "code",
                "metadata": {},
                "execution_count": None,
                "outputs": [],
                "source": ["print('colab roundtrip')\n"],
            }
        ],
        "metadata": {
            "kernelspec": {
                "display_name": "Python 3",
                "language": "python",
                "name": "python3",
            },
            "language_info": {"name": "python"},
        },
        "nbformat": 4,
        "nbformat_minor": 5,
    }


class ColabSessionLifecycleTests(unittest.TestCase):
    """Slice S2's six-operation lifecycle, against the stateful fake CLI:
    the measured submit order, the sentinel-poll mapping table, fetch's
    manifest download and terminal release, D9 cleanup on injected
    failures, D7's budgets per call, and the flag vocabulary the captured
    `help-*.log` surface actually contains.

    `remote_root` is injected as a temp directory (the adapter's own
    constructor parameter, default `/content/.psmith`), which is what
    lets every rendered template execute for real on this machine.
    """

    def _adapter(self, sim: _ColabCLISimulator, **kwargs: object) -> "COLAB.ColabAdapter":
        return COLAB.ColabAdapter(
            colab_executable=str(sim.executable),
            remote_root=str(sim.remote_root),
            **kwargs,
        )

    def _job_folder(self, tmp: str, *, name: str = "search-a", config: dict | None = None) -> Path:
        folder = Path(tmp) / "tools" / "colab" / name
        folder.mkdir(parents=True, exist_ok=True)
        payload = config if config is not None else {
            "schemaVersion": 1,
            "commit": "c" * 40,
            "repo": {
                "url": "https://example.invalid/repo.git",
                "ref": "refs/heads/main",
            },
            "clonePaths": ["src/pkg"],
            "run": {"module": "pkg.harness", "function": "run", "kwargs": {}},
        }
        (folder / "run-config.json").write_text(json.dumps(payload), encoding="utf-8")
        (folder / "runner.ipynb").write_text(
            json.dumps(_colab_trivial_notebook()), encoding="utf-8"
        )
        return folder

    def _expected_session_name(self, folder: Path, *, mode: str = "full") -> str:
        commit = json.loads(
            (folder / "run-config.json").read_text(encoding="utf-8")
        )["commit"]
        digest = COLAB._digest8((folder / "runner.ipynb").read_bytes(), commit, mode)
        return "psmith-%s-%s" % (COLAB._slugify(folder.name), digest)

    def _fast_knobs(self, **overrides: object) -> dict:
        """The fast submit path: the mkdir and dependency-probe helpers
        run for REAL (both are a few stdlib lines, and the real mkdir is
        what actually creates the remote directory the uploads need);
        only the launcher is overridden, so no kernel is spawned.
        """
        knobs: dict = {
            "exec": {
                "launch.py": {"stdout": json.dumps({"launched_pid": 4242}) + "\n"}
            }
        }
        knobs.update(overrides)
        return knobs

    def _submit(self, adapter: "COLAB.ColabAdapter", folder: Path, *, run_config: dict | None = None) -> "ADAPTER.Submission":
        return adapter.submit(
            ADAPTER.Job(
                entrypoint=folder / "runner.ipynb",
                run_config=run_config if run_config is not None else {},
                worker="colab",
            )
        )

    # -- the round trip ---------------------------------------------------

    def test_colab_submit_poll_fetch_roundtrip_with_fake_cli(self) -> None:
        """The done-when's own round trip, end to end: a real submit
        against the fake CLI, a REAL detached `executor.py` executing a
        real notebook with the venv's own kernel, the sentinel poll
        observing completion, fetch downloading the manifest, and the
        terminal release making a later poll honestly `unknown`.
        """
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario()
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim)
            submission = self._submit(adapter, folder)
            self.assertTrue(submission.id.startswith("colab/psmith-search-a-"))
            session_name = submission.id.split("/", 1)[1]

            deadline = time.time() + 120
            state = None
            while time.time() < deadline:
                state = adapter.poll(submission.id)
                if state.state in ("complete", "failed"):
                    break
                time.sleep(0.5)
            if state is None or state.state != "complete":
                log = sim.session_dir(session_name) / "stdout.log"
                detail = log.read_text(encoding="utf-8", errors="replace") if log.is_file() else "<no log>"
                self.fail("executor did not complete: %r; stdout.log: %s" % (state, detail))
            self.assertTrue(state.detail.startswith("[psmith-"))

            destination = Path(tmp) / "fetched"
            fetched = adapter.fetch(submission.id, destination)
            self.assertTrue(fetched.complete)
            self.assertIn("runner.executed.ipynb", fetched.files)
            self.assertTrue((destination / "runner.executed.ipynb").is_file())

            after = adapter.poll(submission.id)
            self.assertEqual(after.state, "unknown")
            self.assertEqual(adapter.list_active("colab"), [])

            tokens = sim.invocations()
            first_download = next(
                index for index, entry in enumerate(tokens) if entry[0] == "download"
            )
            stop_index = next(
                index for index, entry in enumerate(tokens) if entry[0] == "stop"
            )
            self.assertLess(
                first_download,
                stop_index,
                "the release must run after the bytes are local (D9)",
            )

    # -- submit: naming, pre-check, merge, cleanup, installs ---------------

    def test_colab_submit_refuses_an_existing_session_name_before_new(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario()
            folder = self._job_folder(tmp)
            name = self._expected_session_name(folder)
            sim.seed_session(name)
            adapter = self._adapter(sim)
            with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                self._submit(adapter, folder)
            self.assertIn(name, str(ctx.exception))
            self.assertNotIn(
                "new",
                sim.subcommands(),
                "`new` ran against an existing name — the one measured REPLACE",
            )

    def test_colab_submit_name_is_deterministic_and_mode_sensitive(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario(**self._fast_knobs())
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim)

            first = self._submit(adapter, folder)
            adapter.cancel(first.id)
            second = self._submit(adapter, folder)
            self.assertEqual(first.id, second.id)
            adapter.cancel(second.id)

            smoke = self._submit(adapter, folder, run_config={"mode": "smoke"})
            self.assertNotEqual(smoke.id, first.id)
            self.assertTrue(smoke.id.startswith("colab/psmith-search-a-"))

    def test_colab_submit_merges_run_config_like_kaggle(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario(**self._fast_knobs())
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim)
            original = (folder / "run-config.json").read_bytes()

            plain = self._submit(adapter, folder)
            adapter.cancel(plain.id)
            uploaded = sim.session_dir(plain.id.split("/", 1)[1]) / "run-config.json"
            self.assertEqual(
                uploaded.read_bytes(),
                original,
                "an empty job run_config must upload the file's bytes verbatim",
            )

            smoke = self._submit(
                adapter, folder, run_config={"mode": "smoke", "units": ["u1"]}
            )
            merged = json.loads(
                (sim.session_dir(smoke.id.split("/", 1)[1]) / "run-config.json").read_text(
                    encoding="utf-8"
                )
            )
            self.assertEqual(merged["mode"], "smoke")
            self.assertEqual(merged["units"], ["u1"])
            self.assertEqual(
                merged["commit"],
                json.loads(original)["commit"],
                "the merge must not clobber the file's own top-level keys",
            )
            self.assertEqual(
                (folder / "run-config.json").read_bytes(),
                original,
                "the job folder's bytes are never written",
            )

    def test_colab_submit_cleans_up_on_injected_failures(self) -> None:
        """D9's cleanup boundary, including `new`'s own failure modes (the
        ledger's S2-J2 fold-in): every case must stop what it started,
        and a cleanup that also fails must ride on the refusal, not
        replace it.
        """
        cases = {
            "new fails": ({"new_fail": True}, "did not report READY"),
            "new times out": ({"new_no_ready": True}, "did not report READY"),
            "mkdir exec fails": (
                {
                    "exec": {
                        "remote-mkdir.py": {"stdout": "", "stderr": "no dir\n", "exit": 3}
                    }
                },
                "remote mkdir",
            ),
            "upload fails": (
                {
                    "exec": self._fast_knobs()["exec"],
                    "upload_fail": "runner.ipynb",
                },
                "upload",
            ),
            "probe still missing after install": (
                {
                    "exec": self._fast_knobs()["exec"],
                    "probe_missing": ["nbclient"],
                    "install_no_effect": True,
                },
                "still cannot import",
            ),
            "launch exec fails": (
                {
                    "exec": {
                        "launch.py": {"stdout": "", "stderr": "boom\n", "exit": 7}
                    }
                },
                "launch",
            ),
        }
        for label, (knobs, expected) in cases.items():
            with self.subTest(case=label):
                with tempfile.TemporaryDirectory() as tmp:
                    sim = _ColabCLISimulator(tmp)
                    sim.scenario(**knobs)
                    folder = self._job_folder(tmp)
                    adapter = self._adapter(sim)
                    with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                        self._submit(adapter, folder)
                    self.assertIn(expected, str(ctx.exception))
                    self.assertIn(
                        "stop",
                        sim.subcommands(),
                        "D9: a failure after `new` must attempt the stop",
                    )
                    name = self._expected_session_name(folder)
                    self.assertNotIn(
                        name,
                        sim.sessions_on_sim(),
                        "the session survived its own refusal",
                    )

    def test_colab_submit_installs_only_missing_probed_dependencies(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario(**self._fast_knobs(), probe_missing=["jupyter_client"])
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim)
            submission = self._submit(adapter, folder)
            session_name = submission.id.split("/", 1)[1]
            installs = [entry for entry in sim.invocations() if entry[0] == "install"]
            self.assertEqual(
                installs,
                [["install", "-s", session_name, "jupyter_client"]],
                "the install must name exactly the missing package, once",
            )
            probes = [
                entry
                for entry in sim.invocations()
                if entry[0] == "exec"
                and entry[entry.index("-f") + 1].endswith("dependency-probe.py")
            ]
            self.assertEqual(len(probes), 2, "one probe before, one re-probe after")
            self.assertNotIn("stop", sim.subcommands())

    def test_colab_accelerator_mapping_and_refusals(self) -> None:
        """SD18/D13: a declared `sm_*` architecture becomes the matching
        `--gpu` variant on `new`, and anything the table cannot map
        refuses BEFORE any CLI call — never a silent CPU fallback, and
        never an invented TPU mapping.
        """

        def config_with(accelerator: object) -> dict:
            return {
                "schemaVersion": 1,
                "commit": "c" * 40,
                "repo": {
                    "url": "https://example.invalid/repo.git",
                    "ref": "refs/heads/main",
                },
                "clonePaths": ["src/pkg"],
                "run": {"module": "pkg.harness", "function": "run", "kwargs": {}},
                "accelerator": accelerator,
            }

        for architecture, variant in (
            ("sm_75", "T4"),
            ("sm_80", "A100"),
            ("sm_90", "H100"),
        ):
            with self.subTest(mapped=architecture):
                with tempfile.TemporaryDirectory() as tmp:
                    sim = _ColabCLISimulator(tmp)
                    sim.scenario(**self._fast_knobs())
                    folder = self._job_folder(
                        tmp,
                        config=config_with(
                            {"kind": "cuda", "architectures": [architecture]}
                        ),
                    )
                    adapter = self._adapter(sim)
                    submission = self._submit(adapter, folder)
                    adapter.cancel(submission.id)
                    new_calls = [entry for entry in sim.invocations() if entry[0] == "new"]
                    self.assertEqual(len(new_calls), 1)
                    self.assertIn("--gpu", new_calls[0])
                    self.assertEqual(
                        new_calls[0][new_calls[0].index("--gpu") + 1], variant
                    )

        refusals = {
            "unknown architecture": {"kind": "cuda", "architectures": ["sm_50"]},
            "tpu kind": {"kind": "tpu", "architectures": ["sm_75"]},
            "other kind": {"kind": "xgpu", "architectures": ["sm_75"]},
            "zero architectures": {"kind": "cuda", "architectures": []},
            "two architectures": {
                "kind": "cuda",
                "architectures": ["sm_75", "sm_80"],
            },
            "non-list architectures": {"kind": "cuda", "architectures": "sm_75"},
        }
        for label, accelerator in refusals.items():
            with self.subTest(refused=label):
                with tempfile.TemporaryDirectory() as tmp:
                    sim = _ColabCLISimulator(tmp)
                    sim.scenario(**self._fast_knobs())
                    folder = self._job_folder(tmp, config=config_with(accelerator))
                    adapter = self._adapter(sim)
                    with self.assertRaises(COLAB.ColabAdapterError) as ctx:
                        self._submit(adapter, folder)
                    if label == "unknown architecture":
                        self.assertIn("sm_50", str(ctx.exception))
                        self.assertIn("sm_75", str(ctx.exception))
                    self.assertEqual(
                        sim.invocations(),
                        [],
                        "the refusal must land before any CLI call at all",
                    )

        # No declared block: no flag, exactly as before this existed.
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario(**self._fast_knobs())
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim)
            submission = self._submit(adapter, folder)
            adapter.cancel(submission.id)
            new_calls = [entry for entry in sim.invocations() if entry[0] == "new"]
            self.assertEqual(len(new_calls), 1)
            self.assertNotIn("--gpu", new_calls[0])

    # -- poll: the mapping table and the retry rule ------------------------

    def test_colab_poll_maps_the_sentinel_protocol(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            adapter = self._adapter(sim)
            name = "psmith-x-00000000"
            sid = "colab/" + name
            session_dir = sim.session_dir(name)

            sim.scenario(status_not_found=True)
            self.assertEqual(adapter.poll(sid).state, "unknown")

            sim.scenario()
            sim.seed_session(name)
            self.assertEqual(adapter.poll(sid).state, "queued")

            (session_dir).mkdir(parents=True, exist_ok=True)
            (session_dir / "launch.json").write_text(
                json.dumps({"pid": 4321, "started": "2026-09-20T00:00:00Z"}),
                encoding="utf-8",
            )
            running = adapter.poll(sid)
            self.assertEqual(running.state, "running")
            self.assertIn("4321", running.detail)

            (session_dir / "status.json").write_text(
                json.dumps({"exitCode": 0, "finishedAt": "2026-09-20T00:01:00Z"}),
                encoding="utf-8",
            )
            self.assertEqual(adapter.poll(sid).state, "complete")

            (session_dir / "status.json").write_text(
                json.dumps({"exitCode": 3, "finishedAt": "2026-09-20T00:02:00Z"}),
                encoding="utf-8",
            )
            failed = adapter.poll(sid)
            self.assertEqual(failed.state, "failed")
            self.assertEqual(failed.detail, "unit process exited 3")

            sim.scenario(
                exec={"read_state.py": {"stdout": "not json at all\n", "exit": 0}}
            )
            with self.assertRaises(COLAB.ColabAdapterError):
                adapter.poll(sid)

            sim.scenario(
                exec={
                    "read_state.py": {
                        "stdout": "[colab] Session 'psmith-x-00000000' not found.\n",
                        "exit": 1,
                    }
                }
            )
            self.assertEqual(
                adapter.poll(sid).state,
                "unknown",
                "a session that vanishes mid-read is unknown, never a refusal "
                "(ledger S2-J6)",
            )

    def test_colab_poll_surfaces_the_reason_the_executor_recorded(self) -> None:
        """A non-zero exit must carry WHY, because the executor already
        wrote it down.

        `assets/colab/executor.py` records `status.json["error"]` on
        purpose, bounded on purpose (`ERROR_MAX_CHARS`, so a runaway
        traceback cannot turn a completion signal into megabytes). `poll()`
        read `exitCode` out of that same object and reported the number
        alone, so the one field written specifically to explain the failure
        reached nobody -- a field written and read by no one.

        The cost is not theoretical: a run whose notebook could not start
        surfaced as `unit process exited 1` beside a log holding an
        unrelated warning, and the actual reason sat in `status.json` the
        whole time.

        The sibling case above writes a `status.json` with NO `error` key
        and still expects the bare sentence; both are the contract.

        The recorded reason here deliberately avoids the words "not
        found". `_looks_like_not_found()` matches that substring anywhere
        in the helper's output, and the helper's output carries this very
        `status.json`, so a reason containing those words is read as a
        VANISHED SESSION instead of a failed run. That is a separate
        defect with its own entry; this test must not depend on it, in
        either direction.
        """
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            name = "psmith-x-00000000"
            sid = "colab/" + name
            session_dir = sim.session_dir(name)
            adapter = self._adapter(sim)

            sim.scenario()
            sim.seed_session(name)
            session_dir.mkdir(parents=True, exist_ok=True)
            (session_dir / "launch.json").write_text(
                json.dumps({"pid": 99, "started": "2026-09-20T00:00:00Z"}),
                encoding="utf-8",
            )
            (session_dir / "status.json").write_text(
                json.dumps({
                    "exitCode": 1,
                    "finishedAt": "2026-09-20T00:02:00Z",
                    "error": "NoSuchKernel: no kernel named python3 is installed",
                }),
                encoding="utf-8",
            )
            state = adapter.poll(sid)
            self.assertEqual(state.state, "failed")
            self.assertIn("unit process exited 1", state.detail)
            self.assertIn(
                "NoSuchKernel: no kernel named python3 is installed", state.detail,
                "the executor recorded the reason and poll dropped it, so the "
                "caller is told a number and has to go digging for what the "
                "run already knew")

    def test_colab_poll_never_lets_the_runs_own_words_answer_for_the_service(
            self) -> None:
        """A recorded error containing the service's "no such session"
        wording is still a FAILED run, never a vanished session.

        `_looks_like_not_found()` matches that wording anywhere in a
        command's output, and it has to read output rather than the exit
        code, which is measured to be 0 even for a session that does not
        exist. But the state read's output carries the RUN's own words --
        `status.json` verbatim, error text included -- on its last line.
        Scanning that line let the run answer a question about the
        service.

        The consequence is the wrong direction, not merely a wrong label.
        `unknown` means evidence is MISSING, so a caller waiting for a
        terminal state keeps polling or retries; `failed` means stop and
        look. Measured: changing ONLY the wording of the recorded error,
        with every other byte of the scenario identical, flipped the
        verdict from `failed` to `unknown`.

        And it was not hypothetical. The error a run produces when its
        notebook kernel is missing is `NoSuchKernel: ... not found`, so
        this defect would have masked exactly the environment gap that
        `tests/test_forge_gate.py` now probes for.
        """
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            name = "psmith-x-00000000"
            sid = "colab/" + name
            session_dir = sim.session_dir(name)
            adapter = self._adapter(sim)

            sim.scenario()
            sim.seed_session(name)
            session_dir.mkdir(parents=True, exist_ok=True)
            (session_dir / "launch.json").write_text(
                json.dumps({"pid": 99, "started": "2026-09-20T00:00:00Z"}),
                encoding="utf-8",
            )
            (session_dir / "status.json").write_text(
                json.dumps({
                    "exitCode": 1,
                    "finishedAt": "2026-09-20T00:02:00Z",
                    "error": "NoSuchKernel: kernelspec python3 not found",
                }),
                encoding="utf-8",
            )
            state = adapter.poll(sid)
            self.assertEqual(
                state.state, "failed",
                "the run recorded an error whose wording happens to match the "
                "service's own 'no such session' phrase, and the adapter read "
                "the run's words as an answer about the service: a real "
                "failure reported as missing evidence")
            self.assertIn("unit process exited 1", state.detail)
            self.assertIn(
                "kernelspec python3 not found", state.detail,
                "the reason must still travel, wording and all")

    def test_colab_poll_retries_idempotent_reads_once(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            name = "psmith-x-00000000"
            sid = "colab/" + name
            session_dir = sim.session_dir(name)
            session_dir.mkdir(parents=True, exist_ok=True)
            (session_dir / "launch.json").write_text(
                json.dumps({"pid": 99, "started": "2026-09-20T00:00:00Z"}),
                encoding="utf-8",
            )
            sim.seed_session(name)

            sim.scenario(transport_once=["read_state.py"])
            adapter = self._adapter(sim)
            self.assertEqual(adapter.poll(sid).state, "running")
            execs = [entry for entry in sim.invocations() if entry[0] == "exec"]
            self.assertEqual(len(execs), 2, "one retry, exactly")

            with tempfile.TemporaryDirectory() as other:
                sim2 = _ColabCLISimulator(other)
                sim2.seed_session(name)
                sim2.session_dir(name).mkdir(parents=True, exist_ok=True)
                sim2.scenario(hang=["read_state.py"])
                adapter2 = self._adapter(
                    sim2, kernel_timeout=0.5, subprocess_slack=0.2
                )
                with self.assertRaises(COLAB.ColabAdapterError):
                    adapter2.poll(sid)
                execs2 = [entry for entry in sim2.invocations() if entry[0] == "exec"]
                self.assertEqual(len(execs2), 2, "a persistent hang retries once, then refuses")

    def test_colab_launch_is_never_retried(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            sim = _ColabCLISimulator(tmp)
            sim.scenario(hang=["launch.py"])
            folder = self._job_folder(tmp)
            adapter = self._adapter(sim, kernel_timeout=0.5, subprocess_slack=0.2)
            with self.assertRaises(COLAB.ColabAdapterError):
                self._submit(adapter, folder)
